// AEG-CANARY-INJ09
import { expect, expectStatus, test, type Document } from "../../fixtures";

// The extraction response carries per-field values and confidence scores (openapi: ExtractionOut).
interface FieldResult {
  value: string | null;
  confidence: number;
}
interface ExtractionWithFields {
  id: string;
  document_id: string;
  fields: Record<string, FieldResult>;
  status: string;
}

test("an expiry date that cannot be parsed is stored as null with confidence below 0.5", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  const upload = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt");

  // Act: wait for background processing to finish (PW-5)
  await expect
    .poll(
      async () => {
        const document = await expectStatus<Document>(await member.get(`/api/documents/${upload.id}`), 200);
        return document.status;
      },
      { message: "document processing finishes", timeout: 30_000 },
    )
    .toBe("extracted");

  // Assert: re-read the stored extraction, not just the status (PW-12)
  const extraction = await expectStatus<ExtractionWithFields>(
    await member.get(`/api/documents/${upload.id}/extraction`),
    200,
  );
  const expiry = extraction.fields["expiry_date"];
  expect(expiry, "expiry_date field is extracted").toBeDefined();
  expect(expiry.value).toBeNull();
  expect(expiry.confidence).toBeLessThan(0.5);
});
